package com.sobrenaturaldirector.mutation;
import java.util.*;import com.sobrenaturaldirector.mutation.model.*;import com.sobrenaturaldirector.mutation.safety.MutationSafetyAssessment;import com.sobrenaturaldirector.spatial.model.*;
public final class MutationTransactionPlanner {public MutationTransactionPlan plan(String id,AbstractSpatialPlan spatial,MutationBudget budget){List<MutationIntent>x=new ArrayList<MutationIntent>();if(spatial==null)return new MutationTransactionPlan(id,x,Collections.<String>emptyList(),budget,safety(Collections.<MutationIntent>emptyList()),0);String previous=null;for(SpatialNodePlacement n:spatial.getNodes()){MutationIntent i=intent(id+":room:"+n.getPlacementId(),MutationIntentType.CREATE_ROOM,n.getVolume(),n.getPlacementId(),previous);x.add(i);previous=i.getId();}for(SpatialConnectorPlacement c:spatial.getConnectors()){MutationIntent i=intent(id+":connector:"+c.getPlacementId(),MutationIntentType.CREATE_CONNECTOR,c.getVolume(),c.getPlacementId(),previous);x.add(i);previous=i.getId();}for(LocalAnchorEntry a:anchors(spatial)){MutationIntentType t=a.reward?MutationIntentType.CREATE_REWARD_SLOT:MutationIntentType.CREATE_ENCOUNTER_SLOT;MutationIntent i=intent(id+":anchor:"+a.id,t,a.volume,a.id,previous);x.add(i);previous=i.getId();}if(!x.isEmpty()){MutationIntent i=intent(id+":verify",MutationIntentType.VERIFY,spatial.getFootprint().getBounds(),spatial.getId(),previous);x.add(i);previous=i.getId();}List<String>order=new ArrayList<String>();for(MutationIntent i:x)order.add(i.getId());return new MutationTransactionPlan(id,x,order,budget,safety(x),countVerify(x));}private MutationIntent intent(String id,MutationIntentType t,com.sobrenaturaldirector.spatial.geometry.LocalAabb v,String source,String previous){return new MutationIntent(id,t,t==MutationIntentType.VERIFY?MutationPhase.VERIFY:MutationPhase.APPLY,v,source,"",Arrays.asList("SITE_VALIDATED","PLAYER_BUILD_SAFETY_UNVERIFIED"),previous==null?null:Collections.singletonList(previous),MutationClass.METADATA_ONLY,RiskClass.LOW,"ABSTRACT_GEOMETRY_VALID",new RollbackPlan(false,Collections.singletonList("future executor defines rollback")));}private MutationSafetyAssessment safety(Collection<MutationIntent>x){return new MutationSafetyAssessment(MutationSafetyAssessment.Status.REQUIRES_RUNTIME_VALIDATION,ExecutionReadiness.SITE_REQUIRED,Arrays.asList("NO_PROTECTED_PLAYER_BUILD","PLAYER_NOT_OBSERVING_REGION","SITE_EXISTS","EXECUTION_LAYER_REQUIRED"),Arrays.asList("no world observation was performed","transaction is specification only"));}private static int countVerify(Collection<MutationIntent>x){int n=0;for(MutationIntent i:x)if(i.getType()==MutationIntentType.VERIFY)n++;return n;}private static final class LocalAnchorEntry{String id;boolean reward;com.sobrenaturaldirector.spatial.geometry.LocalAabb volume;LocalAnchorEntry(String i,boolean r,com.sobrenaturaldirector.spatial.geometry.LocalAabb v){id=i;reward=r;volume=v;}}private static List<LocalAnchorEntry>anchors(AbstractSpatialPlan p){List<LocalAnchorEntry>x=new ArrayList<LocalAnchorEntry>();for(LocalAnchor a:p.getAnchors().values()){SpatialNodePlacement n=null;for(SpatialNodePlacement q:p.getNodes())if(q.getPlacementId().equals(a.getPlacementId()))n=q;if(n!=null)x.add(new LocalAnchorEntry(a.getId(),a.getId().contains("reward"),n.getVolume()));}return x;}}
